package com.vandorlabs.neoforge.segmented;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import com.vandorlabs.neoforge.client.NativeSegmentedScreen;
import com.vandorlabs.ui.PortholeDialog;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.TitleScreen;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
import java.util.*;
/** Actual native widgets at the title screen; no server/world or invented block registrations. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class SegmentedScreenChecks {
 private static NativeSegmentedScreen screen;private static final List<NativeSegmentedEdit> edits=new ArrayList<>();private static int ticks,stage,checks,frames;private static boolean captured;private static String capture;private static java.util.concurrent.CompletableFuture<Void> reload;
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_SEGMENTED_SCREEN_CHECK"));}
 private static void need(boolean b,String why){checks++;if(!b)throw new AssertionError("Segmented screen stage="+stage+": "+why);}
 private static void click(int id,int button){var widget=screen.button(id);need(widget!=null&&widget.active,"enabled widget "+id);need(screen.mouseClicked(widget.getX()+widget.getWidth()/2D,widget.getY()+widget.getHeight()/2D,button),"actual widget click "+id);}
 private static void tab(int page){int[] pages=screen.settings().window?new int[]{2,3,1}:new int[]{2,1};int at=-1;for(int i=0;i<pages.length;i++)if(pages[i]==page)at=i;need(at>=0,"available page "+page);var p=screen.panel();int width=(p.width-22)/pages.length;need(screen.mouseClicked(p.left+12+at*width+width/2D,p.top+37,0)&&screen.page()==page,"actual tab "+page);}
 private static int frame(){for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(java.util.Set.of("Frame","Frames").contains(ModernFinishCatalog.ENTRIES.get(i).category())&&NativeSegmentedDoorEntity.validTexture(i))return i;throw new AssertionError("fixture frame missing");}
 private static void capture(String file){capture=file;captured=false;frames=0;}
 private static void widgets(Minecraft mc){var tile=new NativeSegmentedDoorEntity(net.minecraft.world.level.block.entity.BlockEntityType.CHEST,BlockPos.ZERO,Blocks.CHEST.defaultBlockState());var menu=new NativeSegmentedMenu(null,37,tile);screen=new NativeSegmentedScreen(menu,new Inventory(null),Component.literal("Segmented Door"),edits::add);screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());need(screen.page()==2&&screen.settings().glass.material==-1,"source fresh page and segmented glazing default");click(6,1);need(screen.settings().direction==3,"reverse slide wraps Right");click(6,0);need(screen.settings().direction==0,"forward slide wraps Up");click(5,1);need(screen.edit().ticks()==20,"reverse speed selects Slow");click(5,0);need(screen.edit().ticks()==10,"forward speed selects Medium");click(14,1);need(screen.settings().position==2,"reverse position selects Far");click(7,1);need(screen.settings().straight,"right click angle toggle");click(8,1);need(screen.settings().layout==0,"reverse artwork layout");click(9,0);need(screen.settings().window&&screen.button(10)!=null&&screen.button(11)!=null,"window controls appear");click(10,1);need(screen.settings().shape==3,"reverse shape selects Round");click(11,1);need(screen.settings().join,"reverse joined-window toggle");tab(3);need(!screen.activePicker().rows().contains(-1),"glass picker has no Original option");screen.choose(PortholeDialog.shadeChoice(18));click(12,1);need(screen.settings().glass.material==-1&&screen.settings().glass.shade==18&&screen.settings().glass.tint==0,"glass palette and reverse tint");boolean rejected=false;try{screen.choose(-1);}catch(IllegalArgumentException expected){rejected=true;}need(rejected,"Original glazing forbidden");tab(2);click(9,0);screen.choose(frame());need(screen.settings().window&&screen.settings().shape==2&&!screen.settings().join,"Frame choice enables source square tiled window");
  tab(1);screen.channelField().setValue("31,");int sent=edits.size();need(!screen.button(0).active,"invalid bank disables Done");click(2,1);need(screen.settings().activation==2&&edits.size()==sent&&screen.channelField().getValue().equals("31,"),"invalid draft refuses transaction and survives reverse activation");tab(2);click(14,1);need(edits.size()==sent&&!screen.button(0).active,"other-page preview cannot apply invalid draft");tab(1);need(screen.channelField().getValue().equals("31,"),"tab change retains invalid draft");screen.channelField().setValue("31, 32");need(screen.button(0).active&&edits.size()==sent+1&&edits.get(edits.size()-1).channels().equals(com.vandorlabs.redstone.ChannelList.of(31,32))&&edits.get(edits.size()-1).operation()==5,"valid bank sends one bounded per-section transaction");screen.channelField().setValue("31, 32");need(edits.size()==sent+1,"duplicate edit suppressed");tab(2);
  var picker=screen.activePicker();picker.searchField().setValue("a");need(picker.rows().size()>picker.visible(),"scrollable filtered source artwork");int before=picker.scroll();var p=screen.panel();need(screen.mouseScrolled(p.listX+5,picker.top()+5,0,-1)&&picker.scroll()>before,"actual wheel scroll");int bottom=picker.top()+picker.visible()*22-1;need(screen.mouseClicked(p.listX+p.listWidth+2,bottom,0),"actual scrollbar press");int end=picker.scroll();need(screen.mouseDragged(p.listX+p.listWidth+2,picker.top(),0,0,-100)&&picker.scroll()<end,"actual scrollbar drag");screen.mouseReleased(0,0,0);tab(3);tab(2);need(screen.activePicker().searchField().getValue().equals("a"),"page change preserves independent query");screen.activePicker().searchField().setValue("panel");need(edits.stream().allMatch(e->e.window()==37&&e.operation()==5&&e.settings().glass.material!=-2),"every emitted edit keeps authenticated window/per-row operation/nonOriginal glass");
 }
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!enabled()||stage==8)return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}need(++ticks<2200,"title timeout");if(ticks<80||mc.getOverlay()!=null||!(mc.screen instanceof TitleScreen))return;need(mc.level==null&&mc.getSingleplayerServer()==null,"title-only widgets, no server/world");if(stage==0){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();stage=6;}else if(stage==6){if(mc.getWindow().getGuiScaledWidth()<600)return;widgets(mc);capture("segmented-door-page.png");stage=1;}else if(stage==1&&captured){tab(3);capture("segmented-glass-page.png");stage=2;}else if(stage==2&&captured){tab(1);capture("segmented-redstone-page.png");stage=3;}else if(stage==3&&captured){tab(2);screen.init(mc,400,260);need(screen.channelField().getValue().equals("31, 32")&&screen.activePicker().searchField().getValue().equals("panel"),"resize retains drafts and query");for(int id:new int[]{0,5,6,7,8,9,10,11,14}){var b=screen.button(id);need(b!=null&&b.getY()>=screen.panel().top&&b.getY()+b.getHeight()<=screen.panel().top+screen.panel().height,"small-screen widget bounds "+id);}reload=mc.reloadResourcePacks();stage=4;}else if(stage==4&&reload.isDone()){reload.join();need(screen.channelField().getValue().equals("31, 32")&&screen.activePicker().searchField().getValue().equals("panel"),"resource reload retains drafts and query");screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());capture("segmented-screen-reloaded.png");stage=5;}else if(stage==5&&captured){System.out.println("[vandorlabs][segmented-screen] title PASS checks="+checks+" edits="+edits.size()+" reverse options invalid drafts shared picker wheel drag resize reload no world");stage=8;mc.stop();}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||screen==null||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var g=event.getGuiGraphics();g.flush();g.pose().pushPose();try{g.pose().translate(0,0,300);g.fill(0,0,Minecraft.getInstance().getWindow().getGuiScaledWidth(),Minecraft.getInstance().getWindow().getGuiScaledHeight(),0xFF101012);screen.render(g,0,0,0);g.flush();}finally{g.pose().popPose();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!enabled()||capture==null||++frames<6)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->{captured=true;});}
}
